from typing import List
import statistics

class MeanAbsoluteDeviationCalculator:
    """ Calculates Mean Absolute Deviation around the mean of a dataset. """

    def __init__(self, numbers: List[float]):
        """ Initializes the calculator with a list of numbers. """
        self.numbers = numbers

    def calculate(self) -> float:
        """ Calculates the Mean Absolute Deviation. """
        mean = statistics.mean(self.numbers)
        deviations = [abs(num - mean) for num in self.numbers]
        return sum(deviations) / len(deviations)

def mean_absolute_deviation(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Mean Absolute Deviation
    around the mean of this dataset.
    """
    calculator = MeanAbsoluteDeviationCalculator(numbers)
    return calculator.calculate()

