def is_palindrome(string: str) -> bool:
    """ Test if given string is a palindrome """
    return string == string[::-1]

def manacher(string: str) -> str:
    """ Find the longest palindromic substring of a given string """
    T = '#'.join('^{}$'.format(string))
    n = len(T)
    P = [0] * n
    C = R = 0

    for i in range(1, n-1):
        if R > i:
            i_mirror = 2*C - i
            P[i] = min(R - i, P[i_mirror])

        while T[i + 1 + P[i]] == T[i - 1 - P[i]]:
            P[i] += 1

        if i + P[i] > R:
            C, R = i, i + P[i]

    max_len, center_index = max((n, i) for i, n in enumerate(P))
    return string[(center_index - max_len)//2: (center_index + max_len)//2]

def longest_palindromic_suffix(string: str) -> str:
    """ Find the longest postfix of supplied string that is a palindrome """
    return manacher(string)

def make_palindrome(string: str) -> str:
    """ Find the shortest palindrome that begins with a supplied string """
    if not string:
        return ''

    suffix = longest_palindromic_suffix(string)
    prefix = string[:string.index(suffix)]
    return string + suffix[::-1]

