class PalindromeFinder:
    def __init__(self, string: str):
        self.string = string

    def is_palindrome(self, s: str) -> bool:
        """Check if a string is a palindrome."""
        return s == s[::-1]

    def longest_palindromic_suffix(self) -> str:
        """Find the longest palindromic suffix of the input string."""
        for i in range(len(self.string), 0, -1):
            if self.is_palindrome(self.string[i:]):
                return self.string[i:]
        return ""

    def make_palindrome(self) -> str:
        """Find the shortest palindrome that begins with the input string."""
        palindromic_suffix = self.longest_palindromic_suffix()
        prefix = self.string[:len(self.string) - len(palindromic_suffix)]
        return self.string + prefix[::-1]

def make_palindrome(string: str) -> str:
    """Find the shortest palindrome that begins with a supplied string."""
    return PalindromeFinder(string).make_palindrome()

